(1, 2, 'Certificado de Conclusão de Curso', 'curso', 'image', '<div style=\"text-align:center; padding:80px 60px; font-family: DejaVu Sans, Arial, sans-serif;\">\r\n\r\n\r\n <br><br><br> <br><br><br>\r\n  <p style=\"font-size:20px; margin-top:40px;\">Certificamos que</p>\r\n\r\n<p style=\"font-size:30px; font-family: DejaVu Serif, Times New Roman, serif; font-style:italic; letter-spacing:1px; font-weight:bold; margin:18px 0;\">\r\n  @{{aluno_nome}}\r\n</p>\r\n\r\n  <p style=\"font-size:18px; line-height:1.6;\">\r\n\r\n    concluiu o curso <strong>@{{curso_nome}}</strong> com carga horária de\r\n\r\n    <strong>@{{carga_horaria}}</strong>.\r\n\r\n  </p>\r\n\r\n<p style=\"font-size:16px; margin-top:22px;\">\r\n  Conclusão em <strong>@{{data_conclusao}}</strong>, em <strong>@{{cidade}}</strong>.\r\n</p>\r\n\r\n\r\n\r\n  <p style=\"margin-top:30px; font-size:14px;\">Código de validação: @{{hash_validacao}}</p>\r\n<p style=\"font-size:15px; margin-top:26px;\">\r\n  @{{escola_legislativa}}\r\n</p>\r\n</div>', 'certificate-templates/7NRKtdLuQjERejbIfxbAExHRSYrd104gJ6qKqD1O.png', 1, '2026-05-09 02:13:05', '2026-05-20 18:37:51'),
(2, 2, 'Modelo Eventos', 'evento', 'image', '<div style=\"text-align:center; padding:80px 60px; font-family: DejaVu Sans, Arial, sans-serif;\">\r\n\r\n\r\n <br><br><br> <br><br><br>\r\n  <p style=\"font-size:20px; margin-top:40px;\">Certificamos que</p>\r\n\r\n<p style=\"font-size:30px; font-family: DejaVu Serif, Times New Roman, serif; font-style:italic; letter-spacing:1px; font-weight:bold; margin:18px 0;\">\r\n  @{{aluno_nome}}\r\n</p>\r\n\r\n  <p style=\"font-size:18px; line-height:1.6;\">\r\n  participou do evento <strong>@{{evento_nome}}</strong>.\r\n</p>\r\n\r\n<p style=\"font-size:16px; margin-top:22px;\">\r\n  Conclusão em <strong>@{{data_conclusao}}</strong>, em <strong>@{{cidade}}</strong>.\r\n</p>\r\n\r\n\r\n\r\n  <p style=\"margin-top:30px; font-size:14px;\">Código de validação: @{{hash_validacao}}</p>\r\n<p style=\"font-size:15px; margin-top:26px;\">\r\n  @{{escola_legislativa}}\r\n</p>\r\n</div>', 'certificate-templates/o8SDpHf5kuIkHqlBtCa7hRum1U9W6MdEI2QzU4bK.png', 1, '2026-05-10 02:54:07', '2026-05-10 03:05:49');
